    assert.equal((await h.renew('a')).ok, false);
    assert.deepEqual(await h.book('a'), { status: 'lent', loans: i, renewed: true });
    assert.deepEqual(await h.giveBack('a'), { ok: true });
    assert.deepEqual(await h.book('a'), { status: 'available', loans: i, renewed: false });
  }
  assert.equal((await h.lend('a')).ok, false);
  assert.deepEqual(await h.retire('a'), { ok: true });
